begin;
create extension if not exists pgtap with schema extensions;
select plan(34);
insert into public.invitations(code,expires_at) values('TEST-AAAA',now()+interval '1 day'),('TEST-BBBB',now()+interval '1 day');
insert into auth.users(id,raw_user_meta_data) values ('11111111-1111-4111-8111-111111111111','{"invite_code":"TEST-AAAA"}'), ('22222222-2222-4222-8222-222222222222','{"invite_code":"TEST-BBBB"}');
select is((select count(*) from public.profiles),2::bigint,'signup creates a profile: a profile means can log in');
select is((select count(*) from public.people where member_id is not null),2::bigint,'every member automatically gets a Person');
select hasnt_table('public','memberships','no memberships table');
select hasnt_table('public','communities','no communities table');
select hasnt_column('public','events','community_id','events have no community');
select hasnt_column('public','events','visibility','events have no visibility');
select hasnt_function('public','is_community_member','no community membership check');
insert into public.events(id,owner_id,title,starts_at) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111','Shared event',now());
insert into public.people(id,created_by,display_name) values('eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee','11111111-1111-4111-8111-111111111111','Guest without account');
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select lives_ok($$insert into public.event_person_tags(event_id,person_id,tagged_by) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee','11111111-1111-4111-8111-111111111111')$$,'creator tags a person without an account');
select throws_ok($$insert into public.event_person_tags(event_id,person_id,tagged_by) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',(select id from public.people where member_id='22222222-2222-4222-8222-222222222222'),'22222222-2222-4222-8222-222222222222')$$,'42501',null,'cannot record a tag as someone else');
select throws_ok($$update public.events set owner_id='22222222-2222-4222-8222-222222222222' where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'$$,'23514',null,'creator identity immutable');
select lives_ok($$update public.events set title='Corrected event' where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'$$,'creator corrects event');
select lives_ok($$update public.profiles set display_name='Author' where id='11111111-1111-4111-8111-111111111111'$$,'own display name editable');
select throws_ok($$insert into public.people(created_by,display_name) values('22222222-2222-4222-8222-222222222222','Forged')$$,'42501',null,'cannot create a person as someone else');
select throws_ok($$update public.people set member_id='11111111-1111-4111-8111-111111111111' where id='eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee'$$,'42501',null,'clients cannot link a person to a member directly');
select throws_ok($$update public.people set created_by='22222222-2222-4222-8222-222222222222' where id='eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee'$$,'42501',null,'person creator cannot be reassigned');
select lives_ok($$update public.people set display_name='Guest renamed' where id='eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee'$$,'creator edits own person');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select is((select count(*) from public.events),1::bigint,'other member can see event');
select is((select count(*) from public.people),3::bigint,'member sees all people');
select is((select count(*) from public.event_person_tags),1::bigint,'member sees tags');
select is((select count(*) from public.event_rsvps),0::bigint,'tagging does not create an RSVP');
with removed as(delete from public.event_person_tags returning person_id) select is((select count(*) from removed),0::bigint,'non-creator cannot delete a tag');
with changed as(update public.events set title='Hijack' returning id) select is((select count(*) from changed),0::bigint,'non-creator cannot edit event');
with removed as(delete from public.events returning id) select is((select count(*) from removed),0::bigint,'non-creator cannot delete event');
with changed as(update public.people set display_name='Hijack' where id='eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee' returning id) select is((select count(*) from changed),0::bigint,'non-creator cannot edit person');
with removed as(delete from public.people where id='eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee' returning id) select is((select count(*) from removed),0::bigint,'non-creator cannot delete person');
select throws_ok($$insert into public.event_person_tags(event_id,person_id,tagged_by) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',(select id from public.people where member_id='22222222-2222-4222-8222-222222222222'),'22222222-2222-4222-8222-222222222222')$$,'42501',null,'non-creator cannot tag');
select lives_ok($$insert into public.event_rsvps(event_id,user_id,status) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','22222222-2222-4222-8222-222222222222','going')$$,'member chooses own going RSVP');
select throws_ok($$update public.event_rsvps set user_id='11111111-1111-4111-8111-111111111111'$$,'23514',null,'RSVP identity cannot be transferred');
select throws_ok($$insert into public.event_rsvps(event_id,user_id,status) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111','going')$$,'42501',null,'cannot RSVP as another user');
select lives_ok($$insert into public.person_claims(person_id,claimant_id) values('eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee','22222222-2222-4222-8222-222222222222')$$,'member claims "this is me" on an unlinked person');
select throws_ok($$select public.confirm_person_claim('eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee','22222222-2222-4222-8222-222222222222')$$,'42501',null,'claimant cannot confirm own claim');
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select lives_ok($$select public.confirm_person_claim('eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee','22222222-2222-4222-8222-222222222222')$$,'person creator confirms the claim');
reset role;
select is((select member_id from public.people where id='eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee'),'22222222-2222-4222-8222-222222222222'::uuid,'confirmed person is linked to the member');
select is((select count(*) from public.people where member_id='22222222-2222-4222-8222-222222222222'),1::bigint,'member keeps a single Person after the claim');
select * from finish();
rollback;
